window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5995f2baf604303a"]={"versions": [{"id": "FIG-5995f2baf604303a", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungslayout / Byte-Stream-Format im Kontext der AUTOSAR Adaptive Platform (ara::com / SOME/IP-Serialisierung). Das Diagramm spezifiziert die physische Anordnung eines eindimensionalen Arrays im Datenstrom, bestehend aus einem vorangestellten Längenfeld und der sequenziellen Nutzdaten-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Length n</strong>: Vorangestelltes Längenfeld mit einer konfigurierbaren Bitbreite von <code>8, 16 or 32 bit</code>.\n</li><li><strong>Element_1 bis Element_n</strong>: Sequenz von Array-Elementen (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, ..., <code>Element_n</code>). Jedes einzelne Element besitzt die feste oder dynamische Elementgröße <code>element size e</code>.\n</li><li><strong>Nutzdatenbereich</strong>: Gesamtheit der Elemente <code>Element_1</code> bis <code>Element_n</code> mit der kumulierten Gesamtlänge <code>n [byte]</code>.\n</li><li>Schnittstelle: Serialisierter Bytestrom zwischen Kommunikationspartnern (Sender/Empfänger bzw. Client/Server).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Repräsentation der Serialisierungsreihenfolge von links nach rechts:</p>\n<ol class=\"fig-list\"><li>Das Feld <code>Length n</code> wird als erstes serialisiert und kodiert die Bytegröße der nachfolgenden Array-Payload.\n</li><li>Unmittelbar folgend werden die Array-Elemente beginnend mit <code>Element_1</code>, danach <code>Element_2</code>, <code>Element_3</code> bis zum abschließenden <code>Element_n</code> kontinuierlich in den Bytestrom geschrieben bzw. deserialisiert.\n</li><li>Die Auswertung beim Empfänger liest zunächst das Längenfeld aus, um die zu lesende Bytezahl <code>n [byte]</code> für die Array-Elemente zu determinieren.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für Serialisierer und Deserialisierer verbindliche Struktur eines eindimensionalen Arrays.\n</li><li>Das Längenfeld quantifiziert die Länge der Payload (<code>n [byte]</code>), nicht die Anzahl der Elemente. Die Anzahl der Elemente ergibt sich aus <code>n / e</code>, sofern Elemente feste Größe besitzen.\n</li><li>Die Bitbreite des Längenfelds ist über Konfiguration/ARXML auf 8, 16 oder 32 Bit festzulegen; Endianness und Element-Padding sind gemäß Protokollspezifikation einzuhalten.\n</li></ul>"}, {"id": "FIG-ff118d02df871dc3", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungslayout / Byte-Stream-Format im Kontext der AUTOSAR Adaptive Platform (ara::com / SOME/IP-Serialisierung). Das Diagramm spezifiziert die physische Anordnung eines eindimensionalen Arrays im Datenstrom, bestehend aus einem vorangestellten Längenfeld und der sequenziellen Nutzdaten-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Length n</strong>: Vorangestelltes Längenfeld mit einer konfigurierbaren Bitbreite von <code>8, 16 or 32 bit</code>.\n</li><li><strong>Element_1 bis Element_n</strong>: Sequenz von Array-Elementen (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, ..., <code>Element_n</code>). Jedes einzelne Element besitzt die feste oder dynamische Elementgröße <code>element size e</code>.\n</li><li><strong>Nutzdatenbereich</strong>: Gesamtheit der Elemente <code>Element_1</code> bis <code>Element_n</code> mit der kumulierten Gesamtlänge <code>n [byte]</code>.\n</li><li>Schnittstelle: Serialisierter Bytestrom zwischen Kommunikationspartnern (Sender/Empfänger bzw. Client/Server).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Repräsentation der Serialisierungsreihenfolge von links nach rechts:</p>\n<ol class=\"fig-list\"><li>Das Feld <code>Length n</code> wird als erstes serialisiert und kodiert die Bytegröße der nachfolgenden Array-Payload.\n</li><li>Unmittelbar folgend werden die Array-Elemente beginnend mit <code>Element_1</code>, danach <code>Element_2</code>, <code>Element_3</code> bis zum abschließenden <code>Element_n</code> kontinuierlich in den Bytestrom geschrieben bzw. deserialisiert.\n</li><li>Die Auswertung beim Empfänger liest zunächst das Längenfeld aus, um die zu lesende Bytezahl <code>n [byte]</code> für die Array-Elemente zu determinieren.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für Serialisierer und Deserialisierer verbindliche Struktur eines eindimensionalen Arrays.\n</li><li>Das Längenfeld quantifiziert die Länge der Payload (<code>n [byte]</code>), nicht die Anzahl der Elemente. Die Anzahl der Elemente ergibt sich aus <code>n / e</code>, sofern Elemente feste Größe besitzen.\n</li><li>Die Bitbreite des Längenfelds ist über Konfiguration/ARXML auf 8, 16 oder 32 Bit festzulegen; Endianness und Element-Padding sind gemäß Protokollspezifikation einzuhalten.\n</li></ul>"}, {"id": "FIG-0056970d88ad620a", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungslayout / Byte-Stream-Format im Kontext der AUTOSAR Adaptive Platform (ara::com / SOME/IP-Serialisierung). Das Diagramm spezifiziert die physische Anordnung eines eindimensionalen Arrays im Datenstrom, bestehend aus einem vorangestellten Längenfeld und der sequenziellen Nutzdaten-Payload.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Length n</strong>: Vorangestelltes Längenfeld mit einer konfigurierbaren Bitbreite von <code>8, 16 or 32 bit</code>.\n</li><li><strong>Element_1 bis Element_n</strong>: Sequenz von Array-Elementen (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, ..., <code>Element_n</code>). Jedes einzelne Element besitzt die feste oder dynamische Elementgröße <code>element size e</code>.\n</li><li><strong>Nutzdatenbereich</strong>: Gesamtheit der Elemente <code>Element_1</code> bis <code>Element_n</code> mit der kumulierten Gesamtlänge <code>n [byte]</code>.\n</li><li>Schnittstelle: Serialisierter Bytestrom zwischen Kommunikationspartnern (Sender/Empfänger bzw. Client/Server).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Repräsentation der Serialisierungsreihenfolge von links nach rechts:</p>\n<ol class=\"fig-list\"><li>Das Feld <code>Length n</code> wird als erstes serialisiert und kodiert die Bytegröße der nachfolgenden Array-Payload.\n</li><li>Unmittelbar folgend werden die Array-Elemente beginnend mit <code>Element_1</code>, danach <code>Element_2</code>, <code>Element_3</code> bis zum abschließenden <code>Element_n</code> kontinuierlich in den Bytestrom geschrieben bzw. deserialisiert.\n</li><li>Die Auswertung beim Empfänger liest zunächst das Längenfeld aus, um die zu lesende Bytezahl <code>n [byte]</code> für die Array-Elemente zu determinieren.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für Serialisierer und Deserialisierer verbindliche Struktur eines eindimensionalen Arrays.\n</li><li>Das Längenfeld quantifiziert die Länge der Payload (<code>n [byte]</code>), nicht die Anzahl der Elemente. Die Anzahl der Elemente ergibt sich aus <code>n / e</code>, sofern Elemente feste Größe besitzen.\n</li><li>Die Bitbreite des Längenfelds ist über Konfiguration/ARXML auf 8, 16 oder 32 Bit festzulegen; Endianness und Element-Padding sind gemäß Protokollspezifikation einzuhalten.\n</li></ul>"}, {"id": "FIG-044eb8551cf30be5", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungslayout / Byte-Stream-Format im Kontext der AUTOSAR Adaptive Platform (ara::com / SOME/IP-Serialisierung). Das Diagramm spezifiziert die physische Anordnung eines eindimensionalen Arrays im Datenstrom mit expliziter Unterscheidung zwischen optionalem Längenfeld und Nutzdaten-Payload sowie den zugehörigen Längenbemaßungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Length n / LengthField (optional)</strong>: Vorangestelltes Längenfeld mit einer konfigurierbaren Bitbreite von <code>8, 16 or 32 bit</code>, gekennzeichnet als optional.\n</li><li><strong>Element_1 bis Element_n</strong>: Sequenz der Array-Elemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, ..., <code>Element_n</code>), jeweils mit der Elementgröße <code>element size e</code>.\n</li><li><strong>n [byte]</strong>: Bemaßungspfeil für die reine Nutzdatenlänge über die Elemente <code>Element_1</code> bis <code>Element_n</code>.\n</li><li><strong>LengthField + n [byte]</strong>: Übergeordneter Bemaßungspfeil für die Gesamtlänge des serialisierten Arrays einschließlich Längenfeld und Nutzdaten.\n</li><li>Schnittstelle: Serialisierter Bytestrom zwischen Kommunikationspartnern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Repräsentation der Serialisierungsreihenfolge von links nach rechts:</p>\n<ol class=\"fig-list\"><li>Falls konfiguriert, wird das optionale Feld <code>LengthField</code> (<code>Length n</code>) vorangestellt, das die Bytegröße der Nutzdaten-Payload anzeigt.\n</li><li>Anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell übertragen.\n</li><li>Der Gesamtumfang des serialisierten Segments umfasst bei Präsenz des Längenfelds die Spanne <code>LengthField + n [byte]</code>, während die reine Elementfolge <code>n [byte]</code> beansprucht. Entfällt das optionale Längenfeld, beginnt die Serialisierung direkt mit <code>Element_1</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Längenfeld ist optional (<code>(optional)</code>); Implementierungen müssen sowohl Konfigurationen mit vorangestelltem Längenfeld als auch ohne Längenfeld (z. B. bei Arrays fixer Größe) unterstützen.\n</li><li>Sofern vorhanden, beträgt die Breite des Längenfelds 8, 16 oder 32 Bit.\n</li><li>Die Gesamtgröße im Bytestrom beträgt <code>LengthField + n [byte]</code> bei vorhandenem Längenfeld bzw. <code>n [byte]</code> bei ausgelassenem Längenfeld.\n</li><li>Parser müssen anhand des Datenmodells auswerten, ob ein <code>LengthField</code> übertragen wird, und die Payload-Länge <code>n [byte]</code> entsprechend abgrenzen.\n</li></ul>"}, {"id": "FIG-8eab96c234fa83cd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungslayout / Byte-Stream-Format im Kontext der AUTOSAR Adaptive Platform (ara::com / SOME/IP-Serialisierung). Das Diagramm spezifiziert die physische Anordnung eines eindimensionalen Arrays im Datenstrom mit expliziter Unterscheidung zwischen optionalem Längenfeld und Nutzdaten-Payload sowie den zugehörigen Längenbemaßungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Length n / LengthField (optional)</strong>: Vorangestelltes Längenfeld mit einer konfigurierbaren Bitbreite von <code>8, 16 or 32 bit</code>, gekennzeichnet als optional.\n</li><li><strong>Element_1 bis Element_n</strong>: Sequenz der Array-Elemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code>, ..., <code>Element_n</code>), jeweils mit der Elementgröße <code>element size e</code>.\n</li><li><strong>n [byte]</strong>: Bemaßungspfeil für die reine Nutzdatenlänge über die Elemente <code>Element_1</code> bis <code>Element_n</code>.\n</li><li><strong>LengthField + n [byte]</strong>: Übergeordneter Bemaßungspfeil für die Gesamtlänge des serialisierten Arrays einschließlich Längenfeld und Nutzdaten.\n</li><li>Schnittstelle: Serialisierter Bytestrom zwischen Kommunikationspartnern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Repräsentation der Serialisierungsreihenfolge von links nach rechts:</p>\n<ol class=\"fig-list\"><li>Falls konfiguriert, wird das optionale Feld <code>LengthField</code> (<code>Length n</code>) vorangestellt, das die Bytegröße der Nutzdaten-Payload anzeigt.\n</li><li>Anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell übertragen.\n</li><li>Der Gesamtumfang des serialisierten Segments umfasst bei Präsenz des Längenfelds die Spanne <code>LengthField + n [byte]</code>, während die reine Elementfolge <code>n [byte]</code> beansprucht. Entfällt das optionale Längenfeld, beginnt die Serialisierung direkt mit <code>Element_1</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Längenfeld ist optional (<code>(optional)</code>); Implementierungen müssen sowohl Konfigurationen mit vorangestelltem Längenfeld als auch ohne Längenfeld (z. B. bei Arrays fixer Größe) unterstützen.\n</li><li>Sofern vorhanden, beträgt die Breite des Längenfelds 8, 16 oder 32 Bit.\n</li><li>Die Gesamtgröße im Bytestrom beträgt <code>LengthField + n [byte]</code> bei vorhandenem Längenfeld bzw. <code>n [byte]</code> bei ausgelassenem Längenfeld.\n</li><li>Parser müssen anhand des Datenmodells auswerten, ob ein <code>LengthField</code> übertragen wird, und die Payload-Länge <code>n [byte]</code> entsprechend abgrenzen.\n</li></ul>"}], "trans": [{"from": "FIG-5995f2baf604303a", "to": "FIG-ff118d02df871dc3", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ff118d02df871dc3", "to": "FIG-0056970d88ad620a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0056970d88ad620a", "to": "FIG-044eb8551cf30be5", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Erstes Feld: Beschriftung um <code>LengthField</code> und <code>(optional)</code> ergänzt.\n</li><li>Gesamtlängenangabe: Zusätzlicher Maßpfeil unterhalb der Nutzdatenlänge für die Gesamtlänge <code>LengthField + n [byte]</code> über die gesamte Serialisierungsstruktur eingefügt.\n</li></ul>"}, {"from": "FIG-044eb8551cf30be5", "to": "FIG-8eab96c234fa83cd", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
